function topDB(){if(!self.indexedDB)return Promise.resolve(null);return topDatabase??=new Promise(resolve=>{const request=indexedDB.open('stack-lab-unit-top-cache',1);request.onupgradeneeded=()=>request.result.createObjectStore('results',{keyPath:'key'});request.onsuccess=()=>resolve(request.result);request.onerror=request.onblocked=()=>resolve(null);});}
const calculationRevision=self.COOP_UNIT_REVISION;
async function topKey(input){if(!self.crypto?.subtle)return null;return CoopUnitCache.key(input,CoopEngine,CoopEggby,calculationRevision);}
async function readTop(key){const db=key&&await topDB();if(!db)return null;return new Promise(resolve=>{try{const request=db.transaction('results').objectStore('results').get(key);request.onsuccess=()=>resolve(request.result?.result||null);request.onerror=()=>resolve(null);}catch{resolve(null);}});}
async function saveTop(key,result){const db=key&&await topDB();if(!db)return;return new Promise(resolve=>{try{const tx=db.transaction('results','readwrite'),store=tx.objectStore('results');store.put({key,result});const count=store.count();count.onsuccess=()=>{let extra=count.result-160;if(extra>0){const cursor=store.openCursor();cursor.onsuccess=()=>{const item=cursor.result;if(item&&extra-->0){item.delete();item.continue();}};}};tx.oncomplete=tx.onerror=tx.onabort=()=>resolve();}catch{resolve();}});}
async function timedFetch(url,options={}){if(typeof fetch!=='function')return null;const controller=new AbortController(),timer=setTimeout(()=>controller.abort(),2000);try{const response=await fetch(url,{...options,signal:controller.signal});return response.ok?await response.json():null;}catch{return null;}finally{clearTimeout(timer);}}
async function storedTop(key,data,kind='top'){
 const valid=kind==='freeze'?CoopUnitCache.validFreeze:CoopUnitCache.valid,prefix=kind+':',path=kind==='freeze'?'unit-freeze-results':'unit-results',asset=kind==='freeze'?'unit-freeze-defaults':'unit-top-defaults';
 if(!key)return null;const local=await readTop(prefix+key);if(local?.revision===calculationRevision&&valid(local))return{...local,cacheSource:'device'};
 const url='/api/'+path+'?revision='+calculationRevision+'&key='+key,headers=data.cacheToken?{Authorization:'Bearer '+data.cacheToken}:{};
 const remote=timedFetch(url,{headers}).then(data=>{if(data?.result?.revision===calculationRevision&&valid(data.result))return{...data.result,cacheSource:data.source};throw Error('no remote result');});
 const defaults=timedFetch('/'+asset+'.json?revision='+calculationRevision).then(data=>{const result=data?.revision===calculationRevision?data.entries?.[key]:null;if(valid(result))return{...result,cacheSource:'precomputed'};throw Error('no default result');});
 try{const result=await Promise.any([remote,defaults]);await saveTop(prefix+key,result);return result;}catch{return null;}
}
async function prepareFreezeCached(raw,data={}){
 if(!raw.account.freezeSetup?.enabled)return raw;
 const basis=CoopUnitTools.freezeBasis(raw,CoopEngine,CoopData,CoopEggby),key=self.crypto?.subtle?await CoopUnitCache.freezeProfileKey(basis,calculationRevision):null;
 let saved=await storedTop(key,data,'freeze'),source=saved?.cacheSource||'computed';
 if(!(saved?.revision===calculationRevision&&CoopUnitCache.validFreeze(saved))){saved={kind:'freeze',revision:calculationRevision,updatedAt:Date.now(),profile:CoopUnitTools.solveFreeze(basis)};source='computed';}
 if(key)await saveTop('freeze:'+key,saved);
 if(source==='computed'&&key&&data.cacheToken)await timedFetch('/api/unit-freeze-results?revision='+calculationRevision+'&key='+key,{method:'PUT',headers:{'Content-Type':'application/json',Authorization:'Bearer '+data.cacheToken},body:JSON.stringify({result:saved})});
 return{...raw,freezeProfile:saved.profile,freezeCacheSource:source,account:{...raw.account,freezeDamagePercent:saved.profile.share*100}};
}
async function computeTop(raw,data){
 const key=await topKey(raw),cached=await storedTop(key,data);
 if(cached){postMessage({...cached,id:data.id,kind:'top',cached:true,refreshing:!!data.force});if(!data.force)return;}
 postMessage({id:data.id,kind:'top-status',message:cached?'저장된 결과 표시 중 · 새 결과를 계산합니다…':'저장된 동일 조건 결과가 없어 계산합니다…'});
 let lastPreview=0;const started=performance.now();
 const input=await prepareFreezeCached(raw,data),result=await CoopUnitTools.top(input,CoopEngine,CoopData,CoopEggby,p=>{const now=performance.now(),preview=p.evaluated===1||now-lastPreview>=500||p.evaluated===p.total;if(preview)lastPreview=now;postMessage({id:data.id,kind:'top-progress',evaluated:p.evaluated,total:p.total,elapsedMs:now-started,...(preview?{rankings:p.rankings,lib:p.lib,freezeProfile:input.freezeProfile}: {})});});
 for(const r of result.rankings){const checked=CoopUnitTools.row(input,r.gems,CoopEngine,CoopData,CoopEggby,true);r.dps=checked.dps;r.formula=checked.formula;}result.rankings.sort(CoopUnitTools.compareDps);
 const reply={kind:'top',freezeProfile:input.freezeProfile,...result,revision:calculationRevision,updatedAt:Date.now()};await saveTop('top:'+key,reply);
 // Save before the page terminates this Worker. Remote failure never loses the local result.
 if(key&&data.cacheToken)await timedFetch('/api/unit-results?revision='+calculationRevision+'&key='+key,{method:'PUT',headers:{'Content-Type':'application/json',Authorization:'Bearer '+data.cacheToken},body:JSON.stringify({result:reply})});
 postMessage({id:data.id,...reply});
}
self.onmessage=async({data})=>{try{const target=CoopTargets.TARGET_BY_ID.get(data.target);if(!target||target.mode!==data.mode)throw Error('계산 대상을 확인하세요.');if(data.kind==='dealer-tier'){const roster=CoopData.demonsIn('supreme'),account=dealerBenchmarkAccount(),rows=[];for(let index=0;index<roster.length;index++){const slug=roster[index].slug,growth=dealerGrowth(slug),modes=slug==='clara'?['minigun','rocket']:[null];let winner=null;for(const claraMode of modes){const currentAccount=structuredClone(account);if(claraMode)currentAccount.claraMode=claraMode;const input=CoopUnitTools.prepareFreeze({...data,slug,growth,account:currentAccount,targetData:target},CoopEngine,CoopData,CoopEggby),optimized=await CoopUnitTools.top(input,CoopEngine,CoopData,CoopEggby,p=>postMessage({id:data.id,kind:'dealer-progress',index,totalUnits:roster.length,slug,evaluated:p.evaluated,total:p.total})),best=optimized.rankings[0],gems=best?.gems||[],checked=CoopUnitTools.row(input,gems,CoopEngine,CoopData,CoopEggby);if(!winner||checked.dps>winner.dps)winner={slug,dps:checked.dps,gems,level:growth.level,lib:growth.lib,freezeShare:input.freezeProfile?.share??0,claraMode:claraMode||null};}rows.push(winner);postMessage({id:data.id,kind:'dealer-progress',index:index+1,totalUnits:roster.length,slug,evaluated:1,total:1});}rows.sort((a,b)=>b.dps-a.dps||a.slug.localeCompare(b.slug));postMessage({id:data.id,kind:'dealer-results',mode:data.mode,target:data.target,rows});return;}if(data.kind==='positions'){if(!Array.isArray(data.sets)||data.sets.length<1||data.sets.length>3)throw Error('비교 조합은 1~3개입니다.');const input={...data,targetData:target},deps={E:CoopEngine,D:CoopData,H:CoopUnitTools,Egg:CoopEggby,G:CoopGeometry,B:CoopBoss,A:CoopAccount},results=[];for(let index=0;index<data.sets.length;index++){const result=await CoopUnitPositions.search({input,picks:data.sets[index],board:data.board,deps,maxEvaluations:80,timeLimit:45000,evaluate:CoopUnitPositions.evaluator(deps,input),onProgress:p=>postMessage({id:data.id,kind:'position-progress',index,...p})});results.push(result);postMessage({id:data.id,kind:'position-row',index,result});}postMessage({id:data.id,kind:'positions',results});return;}const raw={...data,targetData:target};if(data.kind==='top'){await computeTop(raw,data);return;}const input=await prepareFreezeCached(raw,data);if(data.kind==='recommend'){postMessage({id:data.id,kind:data.kind,freezeProfile:input.freezeProfile,...CoopUnitTools.recommend(input,CoopEngine,CoopData,CoopEggby)});return;}if(!Array.isArray(data.sets)||data.sets.length<1||data.sets.length>3)throw Error('비교 조합은 1~3개입니다.');postMessage({id:data.id,freezeProfile:input.freezeProfile,rows:data.sets.map(g=>CoopUnitTools.row(input,g,CoopEngine,CoopData,CoopEggby,true))});}catch(e){postMessage({id:data.id,error:e.message});}};
